package org.kanger.storage.dumb2;
import org.kanger.*;
import java.nio.file.*;
public class NativeReopenHostProbe {
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]).toAbsolutePath();System.setProperty("user.home",root.resolve("home").toString());
  User user=new User();user.setDatabaseDir(root+java.io.File.separator);DB db=new DB();db.init(user);
  Mind base=new Mind(user);user.setCurrentMind(base);Mind m=(Mind)base.useStorage("Source");user.setCurrentMind(m);
  if(db.getRevision()!=1)throw new AssertionError("Input must be Source R1");
  db.connectContext("Rules");if(db.saveConnections(m)!=2)throw new AssertionError("Expected publication R2");
  user.setCurrentMind(m.closeStorage());System.out.println("HOST_REOPEN_PASS");
 }
}

