import java.util.*;
import org.kanger.storage.dumb2.adapter.TermAdapter;
import org.kanger.storage.dumb2.descriptor.*;
public class TermCodecProbe {
 public static void main(String[] args)throws Exception{
  Descriptor canonical=TermAdapter.INSTANCE.getDescriptor();
  Map<String,StructuralValue> f=new LinkedHashMap<>();
  f.put("id",StructuralValue.int64(0));f.put("mindId",StructuralValue.int64(0));f.put("deleted",StructuralValue.bool(false));
  f.put("kind",StructuralValue.enumeration("TermKind","STRING"));f.put("hash",StructuralValue.int32(19));
  f.put("value",StructuralValue.utf8("anchor"));f.put("index",StructuralValue.int32(0));
  byte[] schema=DescriptorBinaryCodec.encode(canonical),payload=StructuralValueCodec.encode(canonical,StructuralValue.struct(f));
  int n=Integer.parseInt(args[0]);Descriptor parsed=null;
  for(int i=0;i<n;i++){
   if(i%50==0){parsed=DescriptorBinaryCodec.decode(schema);if(!canonical.equals(parsed))throw new AssertionError("Descriptor inequality");}
   Map<String,StructuralValue> decoded=StructuralValueCodec.decode(parsed,payload).asStruct();
   StructuralValue flag=decoded.get("deleted");
   if(flag==null||flag.getKind()!=StructuralValue.Kind.BOOL){System.out.println("K3_CODEC_FAIL iteration="+i+" kind="+(flag==null?"missing":flag.getKind())+" keys="+decoded.keySet());return;}
  }
  System.out.println("K3_CODEC_PASS iterations="+n);
 }
}

